import { useState, useMemo } from 'react';
import { db } from '../firebase';
import { collection, getDocs, writeBatch, doc } from 'firebase/firestore';
import { formatKRW, formatShort } from '../utils/calcMetrics';
import './DataManager.css';

export default function DataManager({ allData, opData, onDataChanged, isAdmin }) {
  const [tab, setTab] = useState('sales');        // 'sales' | 'op'
  const [selected, setSelected] = useState(new Set());
  const [deleting, setDeleting] = useState(false);
  const [expandedYear, setExpandedYear] = useState(null);
  const [expandedStore, setExpandedStore] = useState(null);

  // ── 이지포스 데이터 집계 ──────────────────────────────
  const salesTree = useMemo(() => {
    const tree = {};
    allData.forEach((d) => {
      if (!tree[d.year]) tree[d.year] = {};
      if (!tree[d.year][d.store]) tree[d.year][d.store] = [];
      tree[d.year][d.store].push(d);
    });
    return tree;
  }, [allData]);

  // ── 영업정보 데이터 집계 ──────────────────────────────
  const opTree = useMemo(() => {
    const tree = {};
    opData.forEach((d) => {
      if (!tree[d.year]) tree[d.year] = {};
      if (!tree[d.year][d.store]) tree[d.year][d.store] = [];
      tree[d.year][d.store].push(d);
    });
    return tree;
  }, [opData]);

  const currentTree = tab === 'sales' ? salesTree : opTree;
  const currentData = tab === 'sales' ? allData : opData;

  // ── 전체 선택/해제 ────────────────────────────────────
  const allKeys = useMemo(() => currentData.map((d) => d.key), [currentData]);
  const allSelected = allKeys.length > 0 && allKeys.every((k) => selected.has(k));

  const toggleAll = () => {
    if (allSelected) setSelected(new Set());
    else setSelected(new Set(allKeys));
  };

  const toggleKey = (key) => {
    setSelected((prev) => {
      const next = new Set(prev);
      next.has(key) ? next.delete(key) : next.add(key);
      return next;
    });
  };

  const toggleGroup = (keys) => {
    const allIn = keys.every((k) => selected.has(k));
    setSelected((prev) => {
      const next = new Set(prev);
      if (allIn) keys.forEach((k) => next.delete(k));
      else keys.forEach((k) => next.add(k));
      return next;
    });
  };

  // ── 선택 항목 삭제 ────────────────────────────────────
  const handleDelete = async () => {
    if (selected.size === 0) return;
    if (!window.confirm(`선택한 ${selected.size}개 항목을 삭제할까요?`)) return;

    setDeleting(true);
    try {
      const colName = tab === 'sales' ? 'sales-data' : 'op-data';
      const colRef = collection(db, colName);
      const keys = [...selected];

      for (let i = 0; i < keys.length; i += 400) {
        const batch = writeBatch(db);
        keys.slice(i, i + 400).forEach((key) => {
          batch.delete(doc(colRef, key));
        });
        await batch.commit();
      }

      setSelected(new Set());
      onDataChanged();
    } catch (err) {
      alert('삭제 실패: ' + err.message);
    } finally {
      setDeleting(false);
    }
  };

  // ── 통계 요약 ─────────────────────────────────────────
  const totalSales = allData.reduce((s, d) => s + (d.totalSales || 0), 0);
  const years = Object.keys(salesTree).sort();
  const stores = [...new Set(allData.map((d) => d.store))].sort();

  return (
    <div className="dm-wrap">
      {/* 상단 통계 */}
      <div className="dm-summary">
        <div className="dm-stat">
          <div className="dm-stat-label">전체 데이터</div>
          <div className="dm-stat-value">{allData.length}<span>건</span></div>
        </div>
        <div className="dm-stat">
          <div className="dm-stat-label">연도 범위</div>
          <div className="dm-stat-value">{years.length > 0 ? `${years[0]} ~ ${years[years.length-1]}` : '-'}</div>
        </div>
        <div className="dm-stat">
          <div className="dm-stat-label">매장 수</div>
          <div className="dm-stat-value">{stores.length}<span>개</span></div>
        </div>
        <div className="dm-stat">
          <div className="dm-stat-label">누적 매출</div>
          <div className="dm-stat-value">{formatShort(totalSales)}</div>
        </div>
        <div className="dm-stat">
          <div className="dm-stat-label">영업정보</div>
          <div className="dm-stat-value">{opData.length}<span>건</span></div>
        </div>
      </div>

      {/* 탭 */}
      <div className="dm-tabs">
        <button className={`dm-tab ${tab === 'sales' ? 'active' : ''}`} onClick={() => { setTab('sales'); setSelected(new Set()); }}>
          📊 이지포스 데이터 ({allData.length}건)
        </button>
        <button className={`dm-tab ${tab === 'op' ? 'active' : ''}`} onClick={() => { setTab('op'); setSelected(new Set()); }}>
          📋 영업정보 ({opData.length}건)
        </button>
      </div>

      {/* 툴바 */}
      {isAdmin && (
        <div className="dm-toolbar">
          <label className="dm-check-all">
            <input type="checkbox" checked={allSelected} onChange={toggleAll} />
            전체 선택 ({selected.size}/{currentData.length})
          </label>
          {selected.size > 0 && (
            <button className="dm-delete-btn" onClick={handleDelete} disabled={deleting}>
              {deleting ? '삭제 중...' : `🗑 선택 삭제 (${selected.size}건)`}
            </button>
          )}
        </div>
      )}

      {/* 데이터 트리 */}
      <div className="dm-tree">
        {Object.keys(currentTree).sort().map((year) => {
          const yearData = currentTree[year];
          const yearKeys = Object.values(yearData).flat().map((d) => d.key);
          const yearAllSel = yearKeys.every((k) => selected.has(k));
          const yearSales = Object.values(yearData).flat().reduce((s, d) => s + (d.totalSales || 0), 0);

          return (
            <div key={year} className="dm-year-block">
              <div className="dm-year-row" onClick={() => setExpandedYear(expandedYear === year ? null : year)}>
                {isAdmin && (
                  <input
                    type="checkbox"
                    checked={yearAllSel}
                    onChange={() => toggleGroup(yearKeys)}
                    onClick={(e) => e.stopPropagation()}
                  />
                )}
                <span className="dm-expand">{expandedYear === year ? '▼' : '▶'}</span>
                <span className="dm-year-label">{year}년</span>
                <span className="dm-badge">{yearKeys.length}건</span>
                {tab === 'sales' && <span className="dm-sales">{formatShort(yearSales)}</span>}
              </div>

              {expandedYear === year && Object.keys(yearData).sort().map((store) => {
                const storeItems = yearData[store];
                const storeKeys = storeItems.map((d) => d.key);
                const storeAllSel = storeKeys.every((k) => selected.has(k));
                const storeSales = storeItems.reduce((s, d) => s + (d.totalSales || 0), 0);
                const storeId = `${year}-${store}`;

                return (
                  <div key={store} className="dm-store-block">
                    <div className="dm-store-row" onClick={() => setExpandedStore(expandedStore === storeId ? null : storeId)}>
                      {isAdmin && (
                        <input
                          type="checkbox"
                          checked={storeAllSel}
                          onChange={() => toggleGroup(storeKeys)}
                          onClick={(e) => e.stopPropagation()}
                        />
                      )}
                      <span className="dm-expand">{expandedStore === storeId ? '▼' : '▶'}</span>
                      <span className="dm-store-label">{store}</span>
                      <span className="dm-badge">{storeKeys.length}건</span>
                      {tab === 'sales' && <span className="dm-sales">{formatShort(storeSales)}</span>}
                    </div>

                    {expandedStore === storeId && (
                      <table className="dm-table">
                        <thead>
                          <tr>
                            {isAdmin && <th style={{width:32}}></th>}
                            <th>월</th>
                            {tab === 'sales' ? (
                              <>
                                <th>총 매출</th>
                                <th>상품 수</th>
                              </>
                            ) : (
                              <>
                                <th>영업일수</th>
                                <th>총 고객</th>
                              </>
                            )}
                            <th>키</th>
                          </tr>
                        </thead>
                        <tbody>
                          {storeItems.sort((a, b) => a.month?.localeCompare(b.month)).map((item) => (
                            <tr key={item.key} className={selected.has(item.key) ? 'selected' : ''}>
                              {isAdmin && (
                                <td>
                                  <input
                                    type="checkbox"
                                    checked={selected.has(item.key)}
                                    onChange={() => toggleKey(item.key)}
                                  />
                                </td>
                              )}
                              <td>{parseInt(item.month)}월</td>
                              {tab === 'sales' ? (
                                <>
                                  <td className="td-num">{formatKRW(item.totalSales || 0)}원</td>
                                  <td className="td-num">{item.products?.length || 0}개</td>
                                </>
                              ) : (
                                <>
                                  <td className="td-num">{item.dailyOp?.length || 0}일</td>
                                  <td className="td-num">{formatKRW(item.dailyOp?.reduce((s, d) => s + d.guests, 0) || 0)}명</td>
                                </>
                              )}
                              <td style={{ fontSize: 10, color: '#9ca3af' }}>{item.key}</td>
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    )}
                  </div>
                );
              })}
            </div>
          );
        })}

        {currentData.length === 0 && (
          <div className="dm-empty">업로드된 데이터가 없습니다.</div>
        )}
      </div>
    </div>
  );
}
