import { useMemo } from 'react';
import {
  BarChart, Bar, AreaChart, Area, LineChart, Line, XAxis, YAxis, CartesianGrid,
  Tooltip, Legend, ResponsiveContainer, Cell
} from 'recharts';
import { formatKRW, formatShort, sortByStore, STORE_ORDER } from '../utils/calcMetrics';
import './DaypartCompare.css';

const STORE_COLORS = ['#0d2258','#1d4ed8','#7c3aed','#0f766e','#dc2626','#d97706','#059669','#be185d'];

function storeColor(store) {
  const idx = STORE_ORDER.indexOf(store);
  return STORE_COLORS[idx !== -1 ? idx : 0];
}

export default function DaypartCompare({ opData, filters }) {
  // 매장별 점심/저녁 비교
  const storeData = useMemo(() => {
    const map = {};
    opData.forEach((d) => {
      if (filters.year && d.year !== filters.year) return;
      if (filters.months?.length && !filters.months.includes(d.month)) return;
      if (filters.stores?.length && !filters.stores.includes(d.store)) return;
      
      if (!map[d.store]) {
        map[d.store] = {
          store: d.store,
          lunchSales: 0, lunchGuests: 0, lunchTx: 0,
          dinnerSales: 0, dinnerGuests: 0, dinnerTx: 0
        };
      }
      d.dailyOp.forEach((day) => {
        map[d.store].lunchSales += day.lunchSales || 0;
        map[d.store].lunchGuests += day.lunchGuests || 0;
        map[d.store].lunchTx += day.lunchTxCount || 0;
        map[d.store].dinnerSales += day.dinnerSales || 0;
        map[d.store].dinnerGuests += day.dinnerGuests || 0;
        map[d.store].dinnerTx += day.dinnerTxCount || 0;
      });
    });
    return Object.values(map);
  }, [opData, filters]);

  // 월별 점심/저녁 비율 추이
  const monthlyTrend = useMemo(() => {
    const map = {};
    opData.forEach((d) => {
      if (filters.year && d.year !== filters.year) return;
      if (filters.months?.length && !filters.months.includes(d.month)) return;
      if (filters.stores?.length && !filters.stores.includes(d.store)) return;

      const key = `${d.year}-${String(d.month).padStart(2, '0')}`;
      if (!map[key]) {
        map[key] = { yearMonth: key, lunchSales: 0, dinnerSales: 0 };
      }
      d.dailyOp.forEach((day) => {
        map[key].lunchSales += day.lunchSales || 0;
        map[key].dinnerSales += day.dinnerSales || 0;
      });
    });

    return Object.values(map)
      .sort((a, b) => a.yearMonth.localeCompare(b.yearMonth))
      .map((m) => {
        const total = m.lunchSales + m.dinnerSales;
        return {
          ...m,
          lunchPct: total > 0 ? (m.lunchSales / total * 100) : 0,
          dinnerPct: total > 0 ? (m.dinnerSales / total * 100) : 0
        };
      });
  }, [opData, filters]);

  if (!opData.length) {
    return <div className="daily-empty">영업정보 데이터가 없습니다.</div>;
  }

  const sortedStores = sortByStore(storeData);

  return (
    <div className="daypart-compare">
      {/* 매장별 점심/저녁 비교 */}
      <div className="chart-card">
        <div className="chart-title">매장별 점심/저녁 매출 비교</div>
        <ResponsiveContainer width="100%" height={300}>
          <BarChart data={sortedStores} margin={{ top: 10, right: 20, left: 10, bottom: 5 }}>
            <CartesianGrid strokeDasharray="3 3" stroke="#f0f0f0" />
            <XAxis dataKey="store" tick={{ fontSize: 12 }} />
            <YAxis tickFormatter={formatShort} tick={{ fontSize: 11 }} />
            <Tooltip formatter={(v) => [`${formatKRW(v)}원`, '']} />
            <Legend />
            <Bar dataKey="lunchSales" fill="#d97706" name="점심" radius={[4,0,0,0]} />
            <Bar dataKey="dinnerSales" fill="#0d2258" name="저녁" radius={[4,0,0,0]} />
          </BarChart>
        </ResponsiveContainer>
      </div>

      {/* 월별 점심/저녁 비율 추이 */}
      {monthlyTrend.length > 0 && (
        <div className="chart-card">
          <div className="chart-title">월별 점심/저녁 판매 비율 추이</div>
          <ResponsiveContainer width="100%" height={280}>
            <AreaChart data={monthlyTrend} margin={{ top: 10, right: 20, left: 10, bottom: 5 }}>
              <CartesianGrid strokeDasharray="3 3" stroke="#f0f0f0" />
              <XAxis dataKey="yearMonth" tick={{ fontSize: 11 }} />
              <YAxis label={{ value: '%', angle: -90, position: 'insideLeft' }} tick={{ fontSize: 11 }} />
              <Tooltip formatter={(v) => [`${v.toFixed(1)}%`, '']} />
              <Legend />
              <Area
                type="monotone" dataKey="lunchPct" fill="#fbbf24" stroke="#d97706"
                fillOpacity={0.6} stackId="1" name="점심"
              />
              <Area
                type="monotone" dataKey="dinnerPct" fill="#3b82f6" stroke="#0d2258"
                fillOpacity={0.6} stackId="1" name="저녁"
              />
            </AreaChart>
          </ResponsiveContainer>
        </div>
      )}

      {/* 매장별 점심/저녁 상세 테이블 */}
      <div className="chart-card">
        <div className="chart-title">매장별 점심/저녁 상세 현황</div>
        <table className="data-table">
          <thead>
            <tr>
              <th>매장</th>
              <th colSpan="3">점심</th>
              <th colSpan="3">저녁</th>
            </tr>
            <tr>
              <th></th>
              <th>매출</th><th>고객수</th><th>영수건수</th>
              <th>매출</th><th>고객수</th><th>영수건수</th>
            </tr>
          </thead>
          <tbody>
            {sortedStores.map((s) => (
              <tr key={s.store}>
                <td className="td-store">{s.store}</td>
                <td className="td-num">{formatKRW(s.lunchSales)}원</td>
                <td className="td-num">{formatKRW(s.lunchGuests)}명</td>
                <td className="td-num">{formatKRW(s.lunchTx)}건</td>
                <td className="td-num">{formatKRW(s.dinnerSales)}원</td>
                <td className="td-num">{formatKRW(s.dinnerGuests)}명</td>
                <td className="td-num">{formatKRW(s.dinnerTx)}건</td>
              </tr>
            ))}
            <tr className="total-row">
              <td>합계</td>
              <td className="td-num">{formatKRW(sortedStores.reduce((a, s) => a + s.lunchSales, 0))}원</td>
              <td className="td-num">{formatKRW(sortedStores.reduce((a, s) => a + s.lunchGuests, 0))}명</td>
              <td className="td-num">{formatKRW(sortedStores.reduce((a, s) => a + s.lunchTx, 0))}건</td>
              <td className="td-num">{formatKRW(sortedStores.reduce((a, s) => a + s.dinnerSales, 0))}원</td>
              <td className="td-num">{formatKRW(sortedStores.reduce((a, s) => a + s.dinnerGuests, 0))}명</td>
              <td className="td-num">{formatKRW(sortedStores.reduce((a, s) => a + s.dinnerTx, 0))}건</td>
            </tr>
          </tbody>
        </table>
      </div>
    </div>
  );
}
