import { useState } from 'react';
import { signInWithEmailAndPassword } from 'firebase/auth';
import { auth, ADMIN_EMAIL, VIEWER_EMAIL } from '../firebase';
import './Login.css';

const ADMIN_PW = '170417';
const VIEWER_PW = 'pfcpfc1!';

export default function Login({ onLogin }) {
  const [pw, setPw] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const handleSubmit = (e) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    if (pw === ADMIN_PW) {
      // 백그라운드에서 Firebase Auth (Firestore 접근용) — 로그인 흐름은 차단 안 함
      signInWithEmailAndPassword(auth, ADMIN_EMAIL, pw).catch(() => {});
      onLogin('admin');
      setLoading(false);
    } else if (pw === VIEWER_PW) {
      signInWithEmailAndPassword(auth, VIEWER_EMAIL, pw).catch(() => {});
      onLogin('viewer');
      setLoading(false);
    } else {
      setError('비밀번호가 올바르지 않습니다.');
      setPw('');
      setLoading(false);
    }
  };

  return (
    <div className="login-wrap">
      <div className="login-card">
        <div className="login-logo">PF Chang's</div>
        <div className="login-title">브랜드 매출 분석 대시보드</div>
        <form onSubmit={handleSubmit} className="login-form">
          <input
            type="password"
            placeholder="비밀번호를 입력하세요"
            value={pw}
            onChange={(e) => { setPw(e.target.value); setError(''); }}
            className="login-input"
            autoFocus
          />
          {error && <div className="login-error">{error}</div>}
          <button type="submit" className="login-btn" disabled={loading}>
            {loading ? '로그인 중...' : '로그인'}
          </button>
        </form>
        <div className="login-hint">본사 담당자 전용 시스템</div>
      </div>
    </div>
  );
}
